\section{Electric charge}

\begin{enumerate}
  \item Like charges repel; unlike charges attract.
  \item Charging methods
  \begin{enumerate}
    \item Rub an acetate strip with a duster $\Rightarrow$ acetate becomes \textbf{positively} charged
          (electrons leave the acetate).
    \item Rub a polystyrene strip with a duster $\Rightarrow$ polystyrene becomes \textbf{negatively} charged
          (electrons move onto the polystyrene).
    \item Charging by a Van de Graaff generator (continuous transfer of charge to a metal dome).
  \end{enumerate}
  \item Charge $Q$; SI unit: coulomb (C). Electron charge $e=-1.6\times 10^{-19}\,\mathrm{C}$.
  \item \textbf{Conservation of charge:} the algebraic sum of charge in an isolated system is constant.
        When two identical metal spheres touch, charge redistributes equally.
  \item Attraction of a \textbf{neutral} object by a charged object (induction)
  \begin{enumerate}
    \item A positively charged rod near a neutral object induces negative charge on the near side
          and positive charge on the far side.
    \item Attraction to the near-side induced charge exceeds repulsion from the far-side charge
          (near side is closer).
    \item Net force: the neutral object is attracted to the charged rod.
  \end{enumerate}
\end{enumerate}

\begin{center}
\begin{tikzpicture}[scale=0.95]
  \fill[red!15] (0,0) circle (0.45);
  \node[font=\small] at (0,0) {$+$};
  \draw[thick] (0,0) circle (0.45);
  \node[below,font=\scriptsize] at (0,-0.55) {charged};
  \draw[thick,fill=gray!15] (2.2,-0.7) rectangle (3.6,0.7);
  \node[font=\scriptsize,blue!60!black] at (2.5,0.25) {$-$};
  \node[font=\scriptsize,blue!60!black] at (2.5,-0.25) {$-$};
  \node[font=\scriptsize,red!60!black] at (3.3,0.25) {$+$};
  \node[font=\scriptsize,red!60!black] at (3.3,-0.25) {$+$};
  \node[below,font=\scriptsize] at (2.9,-0.9) {neutral};
  \draw[-{Latex},thick] (1.0,0.15) -- (2.05,0.15);
  \node[above,font=\scriptsize] at (1.5,0.2) {attract};
\end{tikzpicture}
\end{center}

\ex
The charge of an electron is $e=-1.6\times 10^{-19}\,\mathrm{C}$.
How many extra electrons are gained by a negatively charged rod of charge $-2\times 10^{-8}\,\mathrm{C}$?
\sol
\[
N=\frac{|Q|}{|e|}=\frac{2\times 10^{-8}}{1.6\times 10^{-19}}=1.25\times 10^{11}.
\]

\worked{2012}{24}{B}{86}{../2012_q24.png}{%
$P$--$Q$ repel $\Rightarrow$ same sign; $R$--$S$ repel $\Rightarrow$ same sign;
$Q$--$R$ attract $\Rightarrow$ opposite signs.
So $\{P,Q\}$ share one sign and $\{R,S\}$ the other.
(1)~$P$ and $R$ both negative: impossible.
(2)~$Q$ and $S$ both positive: impossible.
(3)~$P$ positive, $S$ negative: possible.
$\Rightarrow$ \textbf{B}.}

\worked{2015}{21}{B}{73}{../2015_q21.png}{%
Any two attract. Two balls with the \emph{same} nonzero sign would repel --- forbidden.
All three charged cannot make every pair attract.
Consistent picture: \textbf{one uncharged}, other two \textbf{unlike}.
Unlike pair attracts; each charged ball attracts the neutral one by induction.
$\Rightarrow$ \textbf{B}.}

%======================================================================
\section{Coulomb's law}

\begin{enumerate}
  \item The force between two point charges is proportional to the product of the charges and
        inversely proportional to the square of their separation:
        \[
        F=\frac{Q_1 Q_2}{4\pi\varepsilon_0 r^{2}},
        \qquad
        \varepsilon_0=8.85\times 10^{-12}\,\mathrm{C^{2}\,N^{-1}\,m^{-2}},
        \qquad
        k=\frac{1}{4\pi\varepsilon_0}\approx 9.0\times 10^{9}\,\mathrm{N\,m^{2}\,C^{-2}}.
        \]
  \item Direction: like charges $\Rightarrow$ repulsion; unlike $\Rightarrow$ attraction.
        The two forces are equal in magnitude and opposite (Newton's 3rd law).
  \item For several charges, find each Coulomb force on the target charge, then add as
        \textbf{vectors}.
\end{enumerate}

\begin{center}
\begin{tikzpicture}[scale=1.0]
  \fill[red!20] (0,0) circle (0.28); \node[font=\scriptsize] at (0,0) {$+$};
  \fill[blue!20] (3.2,0) circle (0.28); \node[font=\scriptsize] at (3.2,0) {$-$};
  \draw[-{Latex},thick] (0.4,0.15) -- (2.8,0.15);
  \draw[-{Latex},thick] (2.8,-0.15) -- (0.4,-0.15);
  \node[above,font=\scriptsize] at (1.6,0.2) {attract};
  \node[below,font=\scriptsize] at (1.6,-0.9) {$F=k|Q_1 Q_2|/r^{2}$};
\end{tikzpicture}
\end{center}

\ex
Three charges $Q_1=-2\,\mu\mathrm{C}$, $Q_2=+1\,\mu\mathrm{C}$, $Q_3=-3\,\mu\mathrm{C}$ lie on a straight line
with $Q_2$ midway between $Q_1$ and $Q_3$, separation $10\,\mathrm{cm}$ from each.
Find the resultant force on $Q_2$.
\sol
\[
F_{12}=\frac{k|Q_1 Q_2|}{r^{2}}
=\frac{(9\times 10^{9})(2\times 10^{-6})(1\times 10^{-6})}{(0.1)^{2}}=1.80\,\mathrm{N}
\quad\text{(to the left)}.
\]
\[
F_{32}=\frac{(9\times 10^{9})(3\times 10^{-6})(1\times 10^{-6})}{(0.1)^{2}}=2.70\,\mathrm{N}
\quad\text{(to the right)}.
\]
Resultant $=F_{32}-F_{12}=0.90\,\mathrm{N}$ to the right.

\note{Always convert $\mu\mathrm{C}\to\mathrm{C}$ and $\mathrm{cm}\to\mathrm{m}$ before substituting.}

%======================================================================
\section{Electric field}

\begin{enumerate}
  \item An electric field exists in a region where a charge experiences an electric force.
  \item Field lines
  \begin{enumerate}
    \item Direction: from positive toward negative (direction of force on a \textbf{positive} test charge).
    \item Density of lines $\Leftrightarrow$ field strength.
    \item Lines never cross.
  \end{enumerate}
  \item Definition and comparison with $g$:
\end{enumerate}

\begin{center}
\begin{tabular}{@{}lll@{}}
\toprule
 & Gravitational field $g$ & Electric field $E$ \\
\midrule
Definition & force per unit mass & force per unit charge \\
 & $g=F/m$ & $E=F/q$ \\
Point source & $g=GM/r^{2}$ & $E=Q/(4\pi\varepsilon_0 r^{2})$ \\
Unit & $\mathrm{N\,kg^{-1}}$ & $\mathrm{N\,C^{-1}}$ (or $\mathrm{V\,m^{-1}}$) \\
Nature & vector & vector \\
\bottomrule
\end{tabular}
\end{center}

\begin{enumerate}
  \setcounter{enumi}{3}
  \item Point charge: $\displaystyle E=\frac{Q}{4\pi\varepsilon_0 r^{2}}$ (direction away from $+Q$, toward $-Q$).
  \item \textbf{Superposition:} $\vec E_{\mathrm{net}}=\vec E_1+\vec E_2+\cdots$ (vector sum).
  \item Locations where $E=0$
  \begin{enumerate}
    \item Two like charges: $E=0$ between them, closer to the smaller charge.
    \item Two unlike charges: $E=0$ outside, on the side of the smaller charge.
  \end{enumerate}
\end{enumerate}

\begin{center}
\begin{tikzpicture}[scale=0.85]
  % +Q field
  \fill[red!25] (0,0) circle (0.3); \node[font=\small] at (0,0) {$+$};
  \foreach \a in {0,45,90,135,180,225,270,315} {
    \draw[-{Latex},blue!50!black] (\a:0.45) -- (\a:1.35);
  }
  \node[font=\scriptsize] at (0,-1.7) {isolated $+Q$};
  % -Q field
  \begin{scope}[xshift=4.2cm]
    \fill[blue!25] (0,0) circle (0.3); \node[font=\small] at (0,0) {$-$};
    \foreach \a in {0,45,90,135,180,225,270,315} {
      \draw[-{Latex},blue!50!black] (\a:1.35) -- (\a:0.45);
    }
    \node[font=\scriptsize] at (0,-1.7) {isolated $-Q$};
  \end{scope}
  % parallel plates
  \begin{scope}[xshift=8.0cm]
    \draw[thick] (0,-1.2) -- (0,1.2);
    \draw[thick] (1.6,-1.2) -- (1.6,1.2);
    \node[font=\scriptsize] at (0,1.4) {$+$};
    \node[font=\scriptsize] at (1.6,1.4) {$-$};
    \foreach \y in {-0.8,-0.3,0.2,0.7} {
      \draw[-{Latex},blue!50!black] (0.15,\y) -- (1.45,\y);
    }
    \node[font=\scriptsize] at (0.8,-1.7) {uniform field};
  \end{scope}
\end{tikzpicture}
\end{center}

\ex
Two point charges $A$ ($3\times 10^{-8}\,\mathrm{C}$) and $B$ ($-2\times 10^{-8}\,\mathrm{C}$) are $20\,\mathrm{cm}$ apart.
Find the magnitude of the electric field at $B$ due to $A$.
\sol
\[
E=\frac{Q_A}{4\pi\varepsilon_0 r^{2}}
=\frac{(9\times 10^{9})(3\times 10^{-8})}{(0.2)^{2}}=6750\,\mathrm{N\,C^{-1}}.
\]
\remark{Field at $B$ due to $A$ depends only on $Q_A$ and the distance --- not on $Q_B$.}

\ex
Three charges $A$ ($-3\times 10^{-8}\,\mathrm{C}$), $B$ ($2\times 10^{-8}\,\mathrm{C}$) and
$C$ ($2\times 10^{-8}\,\mathrm{C}$) form an equilateral arrangement with side $20\,\mathrm{cm}$.
Find the resultant field at $A$ due to $B$ and $C$.
\sol
\[
E_B=E_C=\frac{(9\times 10^{9})(2\times 10^{-8})}{(0.2)^{2}}=4500\,\mathrm{N\,C^{-1}}.
\]
The two fields at $A$ each make $30^{\circ}$ with the angle bisector:
\[
E_{\mathrm{net}}=2\,E_B\cos 30^{\circ}=2\times 4500\times\tfrac{\sqrt{3}}{2}=7790\,\mathrm{N\,C^{-1}}.
\]

\worked{2012}{25}{B}{49}{../2012_q25.png}{%
(1)~$E=0$: vector cancel for opposite charges only \textbf{outside} beside smaller $-Q$ $\Rightarrow$ \textbf{Z}.
(2)~$V=0$: scalar $k(2Q)/r_{+}+k(-Q)/r_{-}=0\Rightarrow r_{+}=2r_{-}$, between the charges closer to $-Q$ $\Rightarrow$ \textbf{Y}.
$\Rightarrow$ \textbf{B}.}

\worked{2015}{22}{D}{33}{../2015_q22.png}{%
$-4Q$ and $+Q$ are opposite, so $E=0$ cannot lie between them.
Outside, on the side of smaller $+Q$: distance to $-4Q$ must be twice that to $+Q$.
With 3~grid units between charges, that point is 3~units right of $+Q$ $\Rightarrow$ \textbf{Z} $\Rightarrow$ \textbf{D}.}

%======================================================================
\section{Electric potential}

\begin{enumerate}
  \item Definition: electric potential $V$ at a point is the electric potential energy per unit
        positive test charge:
        \[
        V=\frac{U}{q}.
        \]
        Unit: volt (V). Potential is a \textbf{scalar}.
  \item Isolated point charge (taking $V=0$ at infinity):
        \[
        V=\frac{Q}{4\pi\varepsilon_0 r}.
        \]
        Positive charge $\Rightarrow$ positive $V$; negative charge $\Rightarrow$ negative $V$.
  \item Superposition of potential: add algebraically (no directions).
  \item Uniform field between parallel plates (magnitude): $V=Ed$ for plate separation $d$.
  \item Work / energy: $W=q\Delta V$ (change in PE of charge $q$).
  \item Equipotential surfaces / lines
  \begin{enumerate}
    \item Moving a charge along an equipotential: $W=0$ (PE unchanged).
    \item Equipotentials are perpendicular to field lines.
  \end{enumerate}
\end{enumerate}

\begin{center}
\begin{tabular}{@{}lll@{}}
\toprule
 & Electric field $E$ & Electric potential $V$ \\
\midrule
Nature & vector & scalar \\
Point charge & $\propto 1/r^{2}$ & $\propto 1/r$ \\
Zero location & vector cancel & algebraic cancel \\
Link (uniform) & $E=\Delta V/d$ & $V=Ed$ \\
\bottomrule
\end{tabular}
\end{center}

\ex
Charges $A$ ($3\times 10^{-8}\,\mathrm{C}$) and $B$ ($-5\times 10^{-8}\,\mathrm{C}$) are placed as in a right triangle
with $AX=0.22\,\mathrm{m}$ (approx.) and $BX=0.32\,\mathrm{m}$ (approx.).
Find the potential at $X$.
\sol
\[
V_A=\frac{(9\times 10^{9})(3\times 10^{-8})}{0.224}\approx 1200\,\mathrm{V},\quad
V_B=\frac{(9\times 10^{9})(-5\times 10^{-8})}{0.316}\approx -1420\,\mathrm{V}.
\]
\[
V_X=V_A+V_B\approx -220\,\mathrm{V}.
\]
\remark{Unlike $\vec E$, resultant potential is ordinary addition.}

\worked{2014}{23}{B}{53}{../2014_q23.png}{%
Isolated $+Q$: $V=kQ/r$. If $V_X=V$ at 3~grid units, then at $Y$ (2~grid units)
$V_Y=V\cdot(3/2)=\tfrac{3}{2}V$ $\Rightarrow$ \textbf{B}.}

%======================================================================
\section{Uniform field and charged particles}

\begin{enumerate}
  \item Between large parallel plates with p.d.\ $V$ and separation $d$:
        \[
        E=\frac{V}{d}\quad\text{(uniform; direction $+$ plate $\to$ $-$ plate)}.
        \]
  \item Force on charge $q$: $\vec F=q\vec E$ (same direction as $\vec E$ if $q>0$).
  \item Motion (neglect gravity unless stated)
  \begin{enumerate}
    \item Constant acceleration $\vec a=q\vec E/m$.
    \item Entering perpendicular to $\vec E$: parabolic path (like projectile motion).
    \item Speed increases when the particle moves toward lower PE for its sign.
  \end{enumerate}
  \item Oil-drop / floating droplet: $qE=mg$ $\Rightarrow$ $E=mg/q$ (for equilibrium).
  \item Relation along a line: slope of a $V$--$x$ graph is $-E$
        ($V$ falls in the direction of $\vec E$).
\end{enumerate}

\begin{center}
\begin{tikzpicture}[scale=0.9]
  \draw[thick] (0,0) -- (0,2.4); \node[left,font=\small] at (0,2.4) {$+$};
  \draw[thick] (3.2,0) -- (3.2,2.4); \node[right,font=\small] at (3.2,2.4) {$-$};
  \foreach \y in {0.4,1.0,1.6} {
    \draw[-{Latex},blue!50!black] (0.2,\y) -- (3.0,\y);
  }
  \node[font=\scriptsize] at (1.6,-0.35) {$E=V/d$};
  \fill[gray!40] (1.5,1.0) circle (0.12);
  \node[above,font=\scriptsize] at (1.5,1.15) {droplet};
  \draw[-{Latex},thick] (1.5,1.0) -- (1.5,1.7);
  \node[right,font=\scriptsize] at (1.55,1.55) {$qE$};
  \draw[-{Latex},thick] (1.5,1.0) -- (1.5,0.3);
  \node[right,font=\scriptsize] at (1.55,0.45) {$mg$};
\end{tikzpicture}
\end{center}

\ex
An electron is projected from the positive plate toward the negative plate with
$u=1.5\times 10^{6}\,\mathrm{m\,s^{-1}}$. Plate separation $10\,\mathrm{cm}$, $E=5000\,\mathrm{N\,C^{-1}}$.
($m_e=9.1\times 10^{-31}\,\mathrm{kg}$, $|e|=1.6\times 10^{-19}\,\mathrm{C}$.)
\begin{enumerate}
  \item Find the p.d.\ between the plates.
  \item Find the PE gain if the electron reaches the negative plate.
  \item Can it reach the negative plate?
\end{enumerate}
\sol
\begin{enumerate}
  \item $V=Ed=(5000)(0.1)=500\,\mathrm{V}$.
  \item $\Delta U=|e|V=(1.6\times 10^{-19})(500)=8.0\times 10^{-17}\,\mathrm{J}$.
  \item Initial KE $=\tfrac{1}{2}m u^{2}=(0.5)(9.1\times 10^{-31})(1.5\times 10^{6})^{2}=1.02\times 10^{-18}\,\mathrm{J}$.
        Since KE $<\Delta U$ required, the electron \textbf{cannot} reach the negative plate.
\end{enumerate}

\worked{2018}{22}{A}{55}{../2018_q22.png}{%
Floating $+Q$: need upward electric force to balance $mg$.
Force on a positive charge is parallel to $\vec E$, so $\vec E$ is upward and
$E=mg/Q$ $\Rightarrow$ \textbf{A}.}

