%======================================================================
\section{Simple circuit}

\begin{enumerate}
  \item A closed path containing a source of e.m.f.\ (cell/battery) and one or more loads
        (bulbs, resistors) forms a simple circuit.
  \item \textbf{Conventional current} leaves the positive terminal, goes through the external
        circuit, and returns to the negative terminal.
  \item In a single series loop the current is the \textbf{same} at every point.
\end{enumerate}

\begin{center}
\begin{tikzpicture}[scale=1.05,circuit ee IEC,american]
  \draw (0,0) to[battery1] (0,2.2);
  \draw (0,2.2) -- (3.2,2.2) to[lamp] (3.2,0) -- (0,0);
  \draw[-{Latex},thick] (0.6,2.2) -- (2.4,2.2);
  \node[above,font=\scriptsize] at (1.5,2.25) {conventional $I$};
  \draw[-{Latex},thick,blue!60!black] (2.4,0) -- (0.6,0);
  \node[below,font=\scriptsize,blue!60!black] at (1.5,-0.05) {electron flow};
  \node[left,font=\scriptsize] at (0,1.1) {cell};
\end{tikzpicture}
\end{center}

%======================================================================
\section{Current}

\begin{enumerate}
  \item Definition: current is the rate of flow of charge
        \[
        I=\frac{Q}{t}\qquad\text{or}\qquad Q=It.
        \]
  \item SI unit: ampere (A). $1\,\mathrm{A}=1\,\mathrm{C\,s^{-1}}$.
  \item In metals the mobile carriers are electrons (negative). They drift from $-$ to $+$.
  \item Circuit analysis uses \textbf{conventional current} ($+$ to $-$ in the external circuit)
        unless a question asks explicitly about electrons.
\end{enumerate}

\note{Current is not ``used up'' by a bulb. In a series loop the same $I$ leaves and returns to the
battery. The bulb converts electrical \textbf{energy}, not charge.}

%======================================================================
\section{Potential difference, e.m.f.\ and voltage}

